// 一次性探针（只读）: 验「发现4」+「发现5」—— 只读模式必须真只读，认领不许丢索引。
//
// ── 发现4 的判据（需求方 #368 ④ 写死的那条）──
//  构造"索引里有失效楼层"→ 预览一次 → 断言**聊天变量逐字节不变**。
//  **不是"没走到那个分支"，是"根本没写"。**
//
//  怎么做到"逐字节"：在调用前后各取一次聊天变量的完整 JSON 串，逐字符比对。
//  这比"看 saveMeta 有没有被调"强 —— 后者只证明"我知道的那条路没走"，
//  前者证明**整条路都没留下痕迹**（包括将来新增的写点）。
//
// ── v1 为什么红（§十二 #22：返工前先写清上一版错因）──
//  ① 我以为"删掉 存.message[3] 就等于楼层 3 不存在" —— **假宿主会自动补消息**，
//     `chat.messages(3)` 照样返回一条，于是 `missingFloors` 为空，走的是"编号对不上"分支。
//  ② 我造的快照里 `楼层: 5` 与索引一致，精确匹配直接返回，**根本没走到任何写盘点**。
//
//  v2：用 `host.chat.messages` 的**真实行为**造失效 —— 让它对某一层返回空数组。
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { buildTest } from '../build.mjs';
import path from 'node:path';

const 此处 = path.dirname(fileURLToPath(import.meta.url));
const 入口 = path.join(此处, '_probe-found4v2.ts');
const 产物 = path.join(此处, '_probe-found4v2.mjs');

const 源码 = [
  "import { createPinia, setActivePinia } from 'pinia';",
  "setActivePinia(createPinia());",
  "import { loadData, STORAGE_KEY } from '../../src/彼方_NPC幕后生命状态系统/快照';",
  "import { 彼方假宿主 } from '../helpers/彼方假宿主';",
  "",
  "let 通过 = 0, 失败 = 0;",
  "const 断言 = (名, 实际, 期望) => {",
  "  const ok = JSON.stringify(实际) === JSON.stringify(期望);",
  "  if (ok) 通过++; else 失败++;",
  "  console.log('  ' + (ok ? '✅' : '★ ') + '  ' + 名 + (ok ? '' : '  实际=' + JSON.stringify(实际) + ' 期望=' + JSON.stringify(期望)));",
  "};",
  "",
  "const 原I = console.info, 原W = console.warn, 原E = console.error, 原T = console.table;",
  "const 静默 = () => { console.info = () => {}; console.warn = () => {}; console.error = () => {}; console.table = () => {}; };",
  "const 恢复 = () => { console.info = 原I; console.warn = 原W; console.error = 原E; console.table = 原T; };",
  "",
  "/**",
  " * 造一个「索引里有失效楼层」的聊天。",
  " *",
  " * 关键：**让 chat.messages(3) 返回空数组** —— 这才是 loadData 眼里\"楼层不存在\"。",
  " * 直接删 存.message[3] 不管用，假宿主会补一条。",
  " */",
  "function 造聊天() {",
  "  setActivePinia(createPinia());",
  "  const { host, 存 } = 彼方假宿主({ 模型回复: [], 最后楼层号: 5 });",
  "  存.chat['彼方'] = { 版本: 3, 快照楼层: [3, 5], 清空层: 0 };",
  "  存.message[5] = {",
  "    [STORAGE_KEY]: {",
  "      版本: 3, 楼层: 5, 原编号: 5,",
  "      NPC: { 泰丝: { 当前在做: '整理货单' } },",
  "      名单: ['泰丝'], 剧情时间: '2026-01-02 12:30',",
  "    },",
  "  };",
  "  // ★ 让楼层 3 在 loadData 眼里\"不存在\"",
  "  const 原messages = host.chat.messages;",
  "  host.chat.messages = (id) => (id === 3 ? [] : 原messages(id));",
  "  return { host, 存 };",
  "}",
  "",
  "const 取聊天变量 = (存) => JSON.stringify(存.chat);",
  "",
  "try {",
  "  console.log('=== 发现4 ① 只读模式下，聊天变量必须逐字节不变 ===');",
  "  {",
  "    const { host, 存 } = 造聊天();",
  "    const 前 = 取聊天变量(存);",
  "    静默();",
  "    let data;",
  "    try { data = loadData(host, true); } finally { 恢复(); }",
  "    const 后 = 取聊天变量(存);",
  "    console.log('    调用前: ' + 前);",
  "    console.log('    调用后: ' + 后);",
  "    断言('★ 聊天变量逐字节不变', 后 === 前, true);",
  "    断言('[自证] 读到了 NPC（说明它真跑了一遍）', Object.keys(data?.NPC ?? {}), ['泰丝']);",
  "  }",
  "",
  "  console.log('');",
  "  console.log('=== 发现4 ② 自证：非只读时，同一场景必须写盘 ===');",
  "  {",
  "    const { host, 存 } = 造聊天();",
  "    const 前 = 取聊天变量(存);",
  "    静默();",
  "    try { loadData(host, false); } finally { 恢复(); }",
  "    const 后 = 取聊天变量(存);",
  "    console.log('    调用前: ' + 前);",
  "    console.log('    调用后: ' + 后);",
  "    断言('[自证] 非只读时聊天变量变了（它本来会写）', 后 !== 前, true);",
  "    断言('[自证] 失效楼层 3 被从索引里剔掉了', JSON.parse(后)['彼方'].快照楼层.includes(3), false);",
  "    断言('[自证] 有效楼层 5 还在索引里', JSON.parse(后)['彼方'].快照楼层.includes(5), true);",
  "  }",
  "",
  "  console.log('');",
  "  console.log('=== 发现4 ③ 认领分支：只读也不许写 ===');",
  "  {",
  "    setActivePinia(createPinia());",
  "    const { host, 存 } = 彼方假宿主({ 模型回复: [], 最后楼层号: 5 });",
  "    存.chat['彼方'] = { 版本: 3, 快照楼层: [5], 清空层: 0 };",
  "    // 楼层 5 上的快照记的是旧编号 2 → 编号对不上 → 走认领",
  "    存.message[5] = {",
  "      [STORAGE_KEY]: {",
  "        版本: 3, 楼层: 2, 原编号: 2,",
  "        NPC: { 乔尔: { 当前在做: '巡逻' } },",
  "        名单: ['乔尔'], 剧情时间: '2026-01-02 13:00',",
  "      },",
  "    };",
  "    const 前 = 取聊天变量(存);",
  "    静默();",
  "    let data;",
  "    try { data = loadData(host, true); } finally { 恢复(); }",
  "    const 后 = 取聊天变量(存);",
  "    断言('★ 认领分支在只读时也不写盘', 后 === 前, true);",
  "    断言('[自证] 但确实认领到了数据（乔尔）', Object.keys(data?.NPC ?? {}), ['乔尔']);",
  "    断言('[自证] 锚点被改写成当前楼层 5', data?.锚点楼层, 5);",
  "  }",
  "",
  "  console.log('');",
  "  console.log('=== 发现4 ④ 认领分支：非只读时确实写盘（自证）===');",
  "  {",
  "    setActivePinia(createPinia());",
  "    const { host, 存 } = 彼方假宿主({ 模型回复: [], 最后楼层号: 5 });",
  "    存.chat['彼方'] = { 版本: 3, 快照楼层: [5], 清空层: 0 };",
  "    存.message[5] = {",
  "      [STORAGE_KEY]: { 版本: 3, 楼层: 2, 原编号: 2, NPC: { 乔尔: {} }, 名单: ['乔尔'], 剧情时间: '' },",
  "    };",
  "    // ⚠ 判据要看 **存.message[5]**（认领改写的是那一楼的快照），不是 存.chat。",
  "    //   我第一版看 存.chat —— 那里只有索引，而索引恰好没变（[5] → [5]），于是假红。",
  "    const 前楼层 = JSON.stringify(存.message[5]);",
  "    静默();",
  "    try { loadData(host, false); } finally { 恢复(); }",
  "    const 后楼层 = JSON.stringify(存.message[5]);",
  "    断言('[自证] 非只读时认领会改写那一楼的快照', 后楼层 !== 前楼层, true);",
  "    断言('[自证] 快照的楼层被改写成 5', 存.message[5][STORAGE_KEY].楼层, 5);",
  "  }",
  "",
  "  console.log('');",
  "  console.log('=== 发现5 认领后其余快照仍在索引里 ===');",
  "  {",
  "    setActivePinia(createPinia());",
  "    const { host, 存 } = 彼方假宿主({ 模型回复: [], 最后楼层号: 10 });",
  "    // ⚠ 假宿主只造了楼层 1/2/3 —— 索引里写 7/10 的话 `chat.messages(7)` 返回空，",
  "    //   loadData 会把它们算进 missingFloors（楼层不存在）→ 走另一条分支。",
  "    //   必须让这两层真实存在。",
  "    const 原messages = host.chat.messages;",
  "    host.chat.messages = (id) => (id === 7 || id === 10)",
  "      ? [{ message_id: id, role: 'assistant', is_hidden: false, message: '补的楼层 ' + id }]",
  "      : 原messages(id);",
  "    // ★ 关键：**两层的快照编号都必须对不上**，否则会走\"精确匹配\"直接返回，",
  "    //   根本到不了认领分支（我第一版就是这样，测了半天测的是别的路径）。",
  "    //   7 上记的是旧编号 5，10 上记的是旧编号 4 → 都进 编号对不上 → 认领取 10。",
  "    存.chat['彼方'] = { 版本: 3, 快照楼层: [7, 10], 清空层: 0 };",
  "    存.message[7] = {",
  "      [STORAGE_KEY]: { 版本: 3, 楼层: 5, 原编号: 5, NPC: { 甲: {} }, 名单: ['甲'], 剧情时间: '' },",
  "    };",
  "    存.message[10] = {",
  "      [STORAGE_KEY]: { 版本: 3, 楼层: 4, 原编号: 4, NPC: { 乙: {} }, 名单: ['乙'], 剧情时间: '' },",
  "    };",
  "    静默();",
  "    let data;",
  "    try { data = loadData(host, false); } finally { 恢复(); }",
  "    const 索引 = 存.chat['彼方'].快照楼层;",
  "    console.log('    认领后索引: ' + JSON.stringify(索引) + '  认领到: ' + JSON.stringify(Object.keys(data?.NPC ?? {})));",
  "    断言('[自证] 确实走了认领分支（认到 10 上的乙）', Object.keys(data?.NPC ?? {}), ['乙']);",
  "    断言('★ 认领后索引里仍有 7（其余快照没被丢）', 索引.includes(7), true);",
  "    断言('认领到的 10 也在索引里', 索引.includes(10), true);",
  "    断言('索引是升序的', JSON.stringify(索引) === JSON.stringify([...索引].sort((a,b)=>a-b)), true);",
  "  }",
  "",
  "  console.log('');",
  "  console.log('=== 发现5 自证：旧写法会丢掉其余快照 ===');",
  "  {",
  "    const 旧 = (floorId) => [floorId];",
  "    const 新 = (原索引, floorId, missing) => {",
  "      const 集合 = new Set(原索引.filter(f => !missing.includes(f) && f !== floorId));",
  "      集合.add(floorId);",
  "      return [...集合].sort((a, b) => a - b);",
  "    };",
  "    console.log('    旧写法(原索引 [7,10], 认领 10): ' + JSON.stringify(旧(10)));",
  "    console.log('    新写法(原索引 [7,10], 认领 10): ' + JSON.stringify(新([7, 10], 10, [])));",
  "    断言('[自证] 旧写法只剩 1 条（7 成了孤儿）', 旧(10).length, 1);",
  "    断言('[自证] 新写法保留 2 条', 新([7, 10], 10, []).length, 2);",
  "    断言('[自证] 两者确实不同', JSON.stringify(旧(10)) !== JSON.stringify(新([7, 10], 10, [])), true);",
  "  }",
  "}",
  "finally {",
  "  恢复();",
  "}",
  "",
  "console.log('');",
  "console.log('结果: ' + 通过 + ' 通过, ' + 失败 + ' 失败');",
  "process.exit(失败 > 0 ? 1 : 0);",
].join('\n');

writeFileSync(入口, 源码);

await buildTest(入口, 产物);
await import(new URL(`file:///${产物.replace(/\\/g, '/')}`).href);
